189	/**
190	 * Updates an existing knowledge insight identified by its numeric ID.
191	 *
192	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
193	 * for non-integer, zero, or floating-point strings). Validates the request body
194	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
195	 * type mismatches). Extracts `scope` and `project_slug` discriminator fields to
196	 * scope the update to the correct store.
197	 *
198	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
199	 * cleared (removed) on the stored insight.
200	 *
201	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
202	 *
203	 * @param ledgerRoot  Absolute path to the central ledger root.
204	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
205	 * @param body        Parsed request body (any shape — validated here).
206	 * @returns The updated Insight.
207	 */
208	export async function handleUpdateKnowledge(
209	  ledgerRoot: string,
210	  rawId: string,
211	  body: unknown
212	): Promise<Insight> {
213	  const id = parseKnowledgeId(rawId);
214	
215	  const parseResult = KnowledgeUpdateBodySchema.safeParse(body);
216	  if (!parseResult.success) {
217	    validationError('Invalid knowledge update body.', parseResult.error.issues);
218	  }
219	
220	  const { scope, project_slug, superseded_by, ...rest } = parseResult.data;
221	
222	  // Map superseded_by: null → undefined so the field is cleared on the stored insight.
223	  const updates: Parameters<KnowledgeStoreManager['updateInsight']>[1] = {
224	    ...rest,
225	    ...(superseded_by === null ? { superseded_by: undefined } : superseded_by !== undefined ? { superseded_by } : {}),
226	  };
227	
228	  const manager = new KnowledgeStoreManager(ledgerRoot);
229	
230	  try {
231	    return await manager.updateInsight(id, updates, { scope, project_slug });
232	  } catch (err) {
233	    const msg = err instanceof Error ? err.message : String(err);
234	    if (msg.includes('not found')) {
235	      throw new ApiError('NOT_FOUND', 'Insight not found.');
236	    }
237	    throw err;
238	  }
239	}
